class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_closes = {}
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                continue
            bar = data.bars[symbol]
            if bar is not None:
                bars[ticker] = bar

        self._update_market_state(bars)

        if (
            len(bars) != len(self.symbols)
            or not self.spy_sma.is_ready
            or not self.aapl_rsi.is_ready
        ):
            self._advance_spy_cross_state(bars)
            return

        spy_close = bars["SPY"].close
        aapl_close = bars["AAPL"].close

        spy_crossed_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < self.spy_sma.current.value
        )
        if self.spy_lot > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        spy_crossed_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.current.value
        )
        if self.spy_lot == 0 and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            available_cash = self.portfolio.cash_book["USD"].amount
            if available_cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        self._advance_spy_cross_state(bars)

    def _update_market_state(self, bars):
        spy = self.symbols["SPY"]
        if "SPY" in bars:
            self.spy_sma.update(bars["SPY"].end_time, bars["SPY"].close)

        aapl = self.symbols["AAPL"]
        if "AAPL" in bars:
            close = bars["AAPL"].close
            self.aapl_rsi.update(bars["AAPL"].end_time, close)
            previous = self.previous_closes.get(aapl)
            if previous is not None:
                if close < previous:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        for ticker, bar in bars.items():
            self.previous_closes[self.symbols[ticker]] = bar.close

    def _advance_spy_cross_state(self, bars):
        if "SPY" in bars and self.spy_sma.is_ready:
            self.previous_spy_close = bars["SPY"].close
            self.previous_spy_sma = self.spy_sma.current.value

