class ParallelSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_previous_close = None
        self.rsi_changes = 0
        self.rsi_average_gain = 0.0
        self.rsi_average_loss = 0.0
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]
            else:
                complete_slice = False

        # Market-state calculations continue whenever their ticker has a bar,
        # even on a day on which the complete strategy evaluation is skipped.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self._update_aapl_rsi(aapl_close)

        if not complete_slice or not self._all_state_ready():
            return

        spy_close = float(bars["SPY"].close)
        aapl_close = float(bars["AAPL"].close)

        # Sells are evaluated before buys.  Each strategy owns only its lot.
        if self.spy_lot > 0 and self._spy_crosses_below_sma():
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi > 60.0:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crosses_above_sma():
            shares = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.spy_lot = shares

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000.0
            if float(self.portfolio.cash) >= allocation:
                shares = int(allocation // aapl_close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.aapl_lot = shares

    def _all_state_ready(self):
        return (
            len(self.spy_closes) == self.SMA_PERIOD + 1
            and self.aapl_rsi is not None
        )

    def _spy_crosses_above_sma(self):
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:-1]) / self.SMA_PERIOD
        today_sma = sum(closes[1:]) / self.SMA_PERIOD
        return closes[-2] <= yesterday_sma and closes[-1] > today_sma

    def _spy_crosses_below_sma(self):
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:-1]) / self.SMA_PERIOD
        today_sma = sum(closes[1:]) / self.SMA_PERIOD
        return closes[-2] >= yesterday_sma and closes[-1] < today_sma

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        self.rsi_previous_close = close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_changes < self.RSI_PERIOD:
            self.rsi_average_gain += gain
            self.rsi_average_loss += loss
            self.rsi_changes += 1
            if self.rsi_changes == self.RSI_PERIOD:
                self.rsi_average_gain /= self.RSI_PERIOD
                self.rsi_average_loss /= self.RSI_PERIOD
                self.aapl_rsi = self._rsi_value()
            return

        self.rsi_average_gain = (
            self.rsi_average_gain * (self.RSI_PERIOD - 1) + gain
        ) / self.RSI_PERIOD
        self.rsi_average_loss = (
            self.rsi_average_loss * (self.RSI_PERIOD - 1) + loss
        ) / self.RSI_PERIOD
        self.aapl_rsi = self._rsi_value()

    def _rsi_value(self):
        if self.rsi_average_loss == 0.0:
            return 100.0
        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

