            if not data.bars.contains_key(symbol):
                bars = None
                break
            bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to update even when another ticker is
        # missing and strategy evaluation must be skipped.
        spy_bar = data.bars[self.symbols["SPY"]] if data.bars.contains_key(self.symbols["SPY"]) else None
        aapl_bar = data.bars[self.symbols["AAPL"]] if data.bars.contains_key(self.symbols["AAPL"]) else None

        spy_sma = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) == self.SMA_PERIOD:
                spy_sma = sum(self.spy_closes) / self.SMA_PERIOD

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)
            if self.previous_aapl_close is None or aapl_close >= self.previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1

        all_ready = (
            spy_sma is not None
            and self.previous_spy_sma is not None
            and self.aapl_rsi.is_ready
            and self.previous_aapl_close is not None
        )

        if bars is not None and all_ready:
            spy_close = float(bars["SPY"].close)
            aapl_close = float(bars["AAPL"].close)

            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma
            )

            # Evaluate every sell before any buy.
            if (
                self.strategy_a_shares > 0
                and not self.strategy_a_order_pending
                and spy_crossed_below
            ):
                self.strategy_a_order_pending = True
                self.market_order(
                    self.symbols["SPY"], -self.strategy_a_shares, tag="Strategy A"
                )

            if (
                self.strategy_b_shares > 0
                and not self.strategy_b_order_pending
                and float(self.aapl_rsi.current.value) > 60
            ):
                self.strategy_b_order_pending = True
                self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares, tag="Strategy B"
                )

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            )
            if (
                self.strategy_a_shares == 0
                and not self.strategy_a_order_pending
                and spy_crossed_above
            ):
                quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.strategy_a_order_pending = True
                    self.market_order(self.symbols["SPY"], quantity, tag="Strategy A")

            if (
                self.strategy_b_shares == 0
                and not self.strategy_b_order_pending
                and self.aapl_red_streak >= 3
                and float(self.portfolio.cash) >= 20_000
            ):
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.strategy_b_order_pending = True
                    self.market_order(self.symbols["AAPL"], quantity, tag="Strategy B")

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.close)
            self.previous_spy_sma = spy_sma
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.close)

    def on_order_event(self, order_event):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        fill_quantity = int(order_event.fill_quantity)
        if order.tag == "Strategy A":
            self.strategy_a_shares += fill_quantity
            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self.strategy_a_order_pending = False
        elif order.tag == "Strategy B":
            self.strategy_b_shares += fill_quantity
            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                self.strategy_b_order_pending = False

